<script setup lang="ts">
import { computed, onMounted, ref } from "vue"; import { ArrowLeft, Ban, Bell, BellOff, MessagesSquare, RotateCcw, ShieldCheck } from "@lucide/vue"; import { useRoute, useRouter } from "vue-router"; import { toast } from "vue-sonner"; import { adminApi } from "../api/admin.api"; import type { UserDetail } from "../types"; import StatePanel from "../components/StatePanel.vue";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog"; import { Badge } from "@/components/ui/badge"; import { Button } from "@/components/ui/button"; import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"; import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"; import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"; import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"; import { Skeleton } from "@/components/ui/skeleton"; import { Spinner } from "@/components/ui/spinner"; import { Textarea } from "@/components/ui/textarea";
const levels=["A1","A2","B1","B2","C1","C2"]; const route=useRoute(),router=useRouter(); const user=ref<UserDetail|null>(null),loading=ref(true),error=ref(false),action=ref<string|null>(null),banOpen=ref(false),banReason=ref(""),confirmAction=ref<"unban"|"reset"|null>(null); const id=computed(()=>String(route.params.id)),banned=computed(()=>user.value?.status==="banned");const formatDate=(v:string)=>new Date(v).toLocaleString("ru-RU");
async function load(){loading.value=true;error.value=false;try{user.value=await adminApi.getUserById(id.value);}catch{error.value=true;user.value=null;}finally{loading.value=false;}} async function update(key:string,data:Parameters<typeof adminApi.updateUser>[1],success:string){action.value=key;try{user.value=await adminApi.updateUser(id.value,data);toast.success(success);}catch{toast.error("Не удалось обновить пользователя");}finally{action.value=null;}}
async function changeLevel(level:unknown){const nextLevel=typeof level==="string"&&level!=="__none"?level:null;if(!user.value||nextLevel===user.value.languageLevel)return;await update("level",{languageLevel:nextLevel},"Уровень обновлён");} async function toggleDaily(){if(user.value)await update("daily",{dailyPromptEnabled:!user.value.dailyPromptEnabled},"Настройки рассылки обновлены");} async function ban(){await update("ban",{status:"banned",bannedReason:banReason.value.trim()||undefined},"Пользователь заблокирован");if(user.value?.status==="banned"){banOpen.value=false;banReason.value="";}} async function confirm(){const kind=confirmAction.value;if(kind==="unban")await update("unban",{status:"active"},"Пользователь разблокирован");if(kind==="reset"){action.value="reset";try{await adminApi.resetUserProgress(id.value);await load();toast.success("Прогресс сброшен");}catch{toast.error("Не удалось сбросить прогресс");}finally{action.value=null;}}confirmAction.value=null;} onMounted(load);
</script>
<template><section class="flex flex-col gap-6"><Button class="self-start" variant="ghost" @click="router.push('/users')"><ArrowLeft data-icon="inline-start"/>К пользователям</Button><div v-if="loading" class="flex flex-col gap-4"><Skeleton class="h-32 w-full"/><Skeleton class="h-72 w-full"/></div><StatePanel v-else-if="error||!user" title="Пользователь не найден" description="Не удалось получить данные пользователя." retry-label="Повторить" @retry="load"/>
<template v-else><header class="page-header"><div><p class="eyebrow">Карточка пользователя</p><h1 class="flex flex-wrap items-center gap-2">{{user.username||`Пользователь ${user.telegramId}`}}<Badge v-if="banned" variant="destructive">Заблокирован</Badge></h1><p>Telegram ID: {{user.telegramId}}</p></div><div class="header-actions"><Select :model-value="user.languageLevel||'__none'" :disabled="action!==null" @update:model-value="changeLevel"><SelectTrigger aria-label="Уровень языка"><SelectValue placeholder="Уровень"/></SelectTrigger><SelectContent><SelectGroup><SelectItem value="__none">Не указан</SelectItem><SelectItem v-for="level in levels" :key="level" :value="level">{{level}}</SelectItem></SelectGroup></SelectContent></Select><Button :variant="user.dailyPromptEnabled?'outline':'default'" :disabled="action!==null" @click="toggleDaily"><Spinner v-if="action==='daily'" data-icon="inline-start"/><BellOff v-else-if="user.dailyPromptEnabled" data-icon="inline-start"/><Bell v-else data-icon="inline-start"/>{{user.dailyPromptEnabled?'Выключить рассылку':'Включить рассылку'}}</Button><Button v-if="banned" variant="outline" :disabled="action!==null" @click="confirmAction='unban'"><ShieldCheck data-icon="inline-start"/>Разблокировать</Button><Button v-else variant="destructive" :disabled="action!==null" @click="banOpen=true"><Ban data-icon="inline-start"/>Заблокировать</Button><Button variant="destructive" :disabled="action!==null" @click="confirmAction='reset'"><RotateCcw data-icon="inline-start"/>Сбросить прогресс</Button></div></header>
<Button class="self-start" variant="outline" @click="router.push({path:'/sessions',query:{userId:id}})"><MessagesSquare data-icon="inline-start"/>Сессии пользователя</Button>
<Card><CardHeader><CardTitle>Профиль и настройки</CardTitle><CardDescription>Текущие параметры обучения и активности.</CardDescription></CardHeader><CardContent><dl class="details-grid"><div><dt>Имя пользователя</dt><dd>{{user.username||"—"}}</dd></div><div><dt>Рассылка</dt><dd><Badge :variant="user.dailyPromptEnabled?'default':'secondary'">{{user.dailyPromptEnabled?'Включена':'Выключена'}}</Badge></dd></div><div><dt>Время рассылки</dt><dd>{{String(user.dailyPromptHour).padStart(2,"0")}}:{{String(user.dailyPromptMinute).padStart(2,"0")}}</dd></div><div><dt>Часовой пояс</dt><dd>{{user.timezone}}</dd></div><div><dt>Уровень языка</dt><dd>{{user.languageLevel||"—"}}</dd></div><div><dt>Регистрация</dt><dd>{{formatDate(user.createdAt)}}</dd></div><div><dt>Получено промптов</dt><dd>{{user.promptsReceived}}</dd></div><div><dt>Ответов</dt><dd>{{user.responsesCount}}</dd></div><div><dt>Средняя оценка</dt><dd>{{user.averageScore!==null?`${user.averageScore}/10`:"—"}}</dd></div><div v-if="user.bannedAt"><dt>Заблокирован</dt><dd>{{formatDate(user.bannedAt)}}</dd></div><div v-if="user.bannedReason" class="details-grid__wide"><dt>Причина блокировки</dt><dd>{{user.bannedReason}}</dd></div></dl></CardContent></Card>
</template>
<Dialog v-model:open="banOpen"><DialogContent :show-close-button="action!=='ban'" @escape-key-down="action==='ban'&&$event.preventDefault()" @pointer-down-outside="action==='ban'&&$event.preventDefault()"><DialogHeader><DialogTitle>Заблокировать пользователя</DialogTitle><DialogDescription>При необходимости укажите причину — она будет видна в карточке пользователя.</DialogDescription></DialogHeader><FieldGroup><Field><FieldLabel for="ban-reason">Причина блокировки</FieldLabel><Textarea id="ban-reason" v-model="banReason" rows="3" maxlength="500" placeholder="Необязательно"/></Field></FieldGroup><DialogFooter><Button variant="outline" :disabled="action==='ban'" @click="banOpen=false">Отмена</Button><Button variant="destructive" :disabled="action==='ban'" @click="ban"><Spinner v-if="action==='ban'" data-icon="inline-start"/>Заблокировать</Button></DialogFooter></DialogContent></Dialog>
<AlertDialog :open="confirmAction!==null" @update:open="(open)=>{if(!open&&!action)confirmAction=null}"><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{{confirmAction==='reset'?'Сбросить прогресс?':'Разблокировать пользователя?'}}</AlertDialogTitle><AlertDialogDescription>{{confirmAction==='reset'?'Все ответы и история пользователя будут удалены. Это действие нельзя отменить.':'Пользователь снова получит доступ к боту.'}}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel :disabled="action!==null">Отмена</AlertDialogCancel><AlertDialogAction :variant="confirmAction==='reset'?'destructive':'default'" :disabled="action!==null" @click.prevent="confirm"><Spinner v-if="action" data-icon="inline-start"/>{{confirmAction==='reset'?'Сбросить':'Разблокировать'}}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
</section></template>
